/* ---------- Context meter ---------- */
.ctm{padding:16px}
.ctm-h{display:flex;align-items:center;gap:12px}
.ctm-ring{width:34px;height:34px}
.ctm-arc{transition:stroke-dasharray 1s var(--ease)}
.ctm-t{font-weight:500}
.ctm-s{font-size:12.5px;color:var(--muted)}
.ctm-pct{margin-left:auto;font-size:22px;font-weight:600;letter-spacing:-.5px}
.ctm-bar{display:flex;gap:3px;height:8px;margin:16px 0 12px;border-radius:5px;background:repeating-linear-gradient(135deg,var(--line) 0 1.5px,transparent 1.5px 5px)}
.ctm-bar span{height:100%;border-radius:4px;width:0;transition:width 1s var(--ease),opacity .25s,transform .25s var(--ease)}
.ctm-bar.hl span{opacity:.25}
.ctm-bar.hl span.on{opacity:1}
.ctm-leg{display:flex;flex-direction:column}
.ctm-row{display:flex;align-items:center;gap:9px;padding:6px 8px;margin:0 -8px;border-radius:9px;font-size:13px;color:var(--fg2);cursor:default;transition:background .2s,color .2s}
.ctm-row:hover,.ctm-row.on{background:var(--wash);color:var(--fg)}
.ctm-row i{width:8px;height:8px;border-radius:3px}
.ctm-row i.free{background:repeating-linear-gradient(135deg,var(--faint) 0 1px,transparent 1px 3px);box-shadow:inset 0 0 0 1px var(--faint)}
.ctm-row span{margin-left:auto;color:var(--muted)}
.ctm-f{display:flex;align-items:center;gap:10px;margin-top:12px;padding-top:12px;border-top:1px solid var(--line);font-size:12.5px}
.ctm-f .pill{margin-left:auto}

DM.def('context-meter', (r, c) => {
  const total = 200; let v = { files:56, chat:60, tools:20 };
  const bars = $$('.ctm-bar span', r), rows = $$('.ctm-row', r), bar = $('.ctm-bar', r), go = $('.ctm-go', r);
  const shown = { files:0, chat:0, tools:0, free:200, used:0 };
  function paint(){
    const used = v.files + v.chat + v.tools;
    bars.forEach(b => b.style.width = (v[b.dataset.k] / total * 100) + '%');
    $('.ctm-arc', r).setAttribute('stroke-dasharray', (used / total * 100) + ' 100');
    const tgt = { ...v, free: total - used, used };
    Object.keys(tgt).forEach(k => { const from = shown[k]; tween(from, tgt[k], 1000, x => { shown[k] = x;
      if (k === 'used'){ $('.ctm-used', r).textContent = Math.round(x) + 'k'; $('.ctm-pct', r).textContent = Math.round(x / total * 100) + '%'; }
      else { const row = rows.find(rw => rw.dataset.k === k); $('span', row).textContent = Math.round(x) + 'k'; } }); });
  }
  const hl = k => { bar.classList.toggle('hl', !!k); bars.forEach(b => b.classList.toggle('on', b.dataset.k === k)); rows.forEach(rw => rw.classList.toggle('on', rw.dataset.k === k)); };
  bars.forEach(b => { b.dataset.tip = ''; c.on(b, 'pointerenter', () => { hl(b.dataset.k); b.dataset.tip = rows.find(rw => rw.dataset.k === b.dataset.k).firstChild.nextSibling.textContent + ', ' + v[b.dataset.k] + 'k tokens'; }); c.on(b, 'pointerleave', () => hl(null)); });
  rows.forEach(rw => { c.on(rw, 'pointerenter', () => hl(rw.dataset.k === 'free' ? null : rw.dataset.k)); c.on(rw, 'pointerleave', () => hl(null)); });
  let compacted = false;
  go.onclick = () => {
    compacted = !compacted;
    v = compacted ? { files:56, chat:14, tools:6 } : { files:56, chat:60, tools:20 };
    swap(go, compacted ? 'Restore' : 'Compact'); go.className = 'pill sm ' + (compacted ? 'soft' : 'ink') + ' ctm-go';
    swap($('.ctm-note', r), compacted ? 'Saved 60k tokens, kept 9 decisions' : 'Compacting keeps decisions, drops the chatter');
    paint();
  };
  c.later(300, paint);
});
